insert into public.creators (id, name, handle, tagline, bio, followers, price_monthly, photo_url, highlights) values
  ('c_marko', 'Marko Petrović', 'marko.lifts', 'Snaga i hipertrofija', 'Trener snage iz Novog Sada. Radim sa šipkom, jednostavno i dosledno. Svaki trening ima jedan glavni pokret.', 48200, 5.99, 'https://images.unsplash.com/photo-1704223523169-52feeed90365?w=400&q=75&auto=format&fit=crop', '[{"id":"h_marko_me","title":"O meni","items":[{"url":"https://images.unsplash.com/photo-1704223523169-52feeed90365?w=1080&q=75&auto=format&fit=crop","video":false},{"url":"https://images.unsplash.com/photo-1704223523303-a5ed14561b1f?w=1080&q=75&auto=format&fit=crop","video":false}]},{"id":"h_marko_how","title":"Kako treniram","items":[{"url":"https://videos.pexels.com/video-files/4488004/4488004-sd_360_640_25fps.mp4","video":true},{"url":"https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=1080&q=75&auto=format&fit=crop","video":false}]},{"id":"h_marko_res","title":"Rezultati","items":[{"url":"https://images.unsplash.com/photo-1770664612843-b44e26070024?w=1080&q=75&auto=format&fit=crop","video":false},{"url":"https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=1080&q=75&auto=format&fit=crop","video":false}]}]'::jsonb),
  ('c_jelena', 'Jelena Ilić', 'jelena.moves', 'Treninzi kod kuće', 'Bučice, trake i 40 minuta. Programi za one koji treniraju u dnevnoj sobi i žele da vide napredak.', 126000, 4.99, 'https://images.unsplash.com/photo-1620862657760-72a639a2daef?w=400&q=75&auto=format&fit=crop', '[{"id":"h_jelena_me","title":"O meni","items":[{"url":"https://images.unsplash.com/photo-1620862657760-72a639a2daef?w=1080&q=75&auto=format&fit=crop","video":false},{"url":"https://images.unsplash.com/photo-1714646442330-9068099f5521?w=1080&q=75&auto=format&fit=crop","video":false}]},{"id":"h_jelena_home","title":"Kod kuće","items":[{"url":"https://videos.pexels.com/video-files/5510124/5510124-sd_360_640_25fps.mp4","video":true},{"url":"https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=1080&q=75&auto=format&fit=crop","video":false}]},{"id":"h_jelena_qa","title":"Pitanja","items":[{"url":"https://images.unsplash.com/photo-1714646442330-9068099f5521?w=1080&q=75&auto=format&fit=crop","video":false}]}]'::jsonb),
  ('c_nikola', 'Nikola Jovanović', 'nikola.fit', 'Kalistenika', 'Vratilo, pod i sopstvena težina. Od prvog zgiba do deset u seriji.', 9400, 3.99, 'https://images.unsplash.com/photo-1634225251578-d5f6ffced78a?w=400&q=75&auto=format&fit=crop', '[{"id":"h_nikola_me","title":"O meni","items":[{"url":"https://images.unsplash.com/photo-1634225251578-d5f6ffced78a?w=1080&q=75&auto=format&fit=crop","video":false},{"url":"https://images.unsplash.com/photo-1634225252941-66fd95aaa7c3?w=1080&q=75&auto=format&fit=crop","video":false}]},{"id":"h_nikola_skill","title":"Prvi zgib","items":[{"url":"https://videos.pexels.com/video-files/7187450/7187450-sd_360_640_24fps.mp4","video":true}]}]'::jsonb),
  ('c_minja', 'Minja Varsaković', 'minjavarsakovicc', 'Snažne noge i gluteus', 'Personalni trener u Beauty & Beast womens gym na Vračaru. Autorka online programa Glutelab i kućnog programa Glutelab 2. Radi sa ženama koje u teretani žele snažne noge i gluteus, trening po trening.', 142000, 4.99, 'asset:assets/trainers/minja/portret.jpg', '[{"id":"h_minja_me","title":"O meni","items":[{"url":"asset:assets/trainers/minja/portret.jpg","video":false}]},{"id":"h_minja_glutelab","title":"Glutelab","items":[{"url":"asset:assets/trainers/minja/program-glutelab.jpg","video":false},{"url":"asset:assets/trainers/minja/trening-quad-day.jpg","video":false},{"url":"asset:assets/trainers/minja/trening-back-day.jpg","video":false},{"url":"asset:assets/trainers/minja/trening-zadnja-loza.jpg","video":false},{"url":"asset:assets/trainers/minja/trening-gornji-deo.jpg","video":false}]}]'::jsonb),
  ('c_kriss', 'Kristina Živanović', 'fitbykriss', 'Snaga i samopouzdanje', 'Fitnes trener za žene koje žele snagu i samopouzdanje. Autorka programa Full Body Project i Glute Summer Challenge, sa planom treninga i smernicama za ishranu. Bilo da je cilj mišići ili mršavljenje, plan je jasan i prati te nedelju po nedelju.', 78200, 4.99, 'asset:assets/trainers/kriss/portret.jpg', '[{"id":"h_kriss_me","title":"O meni","items":[{"url":"asset:assets/trainers/kriss/portret.jpg","video":false}]},{"id":"h_kriss_fbp","title":"Full Body","items":[{"url":"asset:assets/trainers/kriss/program-full-body-project.jpg","video":false},{"url":"asset:assets/trainers/kriss/trening-noge-a.jpg","video":false},{"url":"asset:assets/trainers/kriss/trening-gornji-deo-a.jpg","video":false},{"url":"asset:assets/trainers/kriss/trening-noge-b.jpg","video":false},{"url":"asset:assets/trainers/kriss/trening-gornji-deo-b.jpg","video":false}]}]'::jsonb),
  ('c_anja', 'Anja Blagojević', 'anjablaa', 'Gluteus i forma', 'Trener sa više od tri godine iskustva, kroz program Fit by AnjaBlaa prošlo je 4.000+ devojaka. Plan za kuću ili teretanu, od prvog treninga do napredne forme, uz ishranu po tvojim parametrima.', 1000000, 4.99, 'asset:assets/trainers/anja/portret.jpg', '[{"id":"h_anja_me","title":"O meni","items":[{"url":"asset:assets/trainers/anja/portret.jpg","video":false}]},{"id":"h_anja_fit","title":"Treninzi","items":[{"url":"asset:assets/trainers/anja/program-fit-by-anjablaa.jpg","video":false},{"url":"asset:assets/trainers/anja/trening-gluteus-a.jpg","video":false},{"url":"asset:assets/trainers/anja/trening-gornji-deo.jpg","video":false},{"url":"asset:assets/trainers/anja/trening-gluteus-b.jpg","video":false},{"url":"asset:assets/trainers/anja/trening-trbuh.jpg","video":false}]}]'::jsonb)
