  ('w_kz_upper_b', 'c_kriss', 'Gornji deo B', '[{"exerciseId":"kz_lat","sets":3,"repsMin":10,"repsMax":12,"rir":2,"restSeconds":90},{"exerciseId":"kz_db_press","sets":3,"repsMin":8,"repsMax":10,"rir":2,"restSeconds":90},{"exerciseId":"kz_rear_delt","sets":3,"repsMin":12,"repsMax":15,"rir":1,"restSeconds":60},{"exerciseId":"kz_tri_rope","sets":3,"repsMin":10,"repsMax":12,"rir":1,"restSeconds":60},{"exerciseId":"kz_db_curl","sets":3,"repsMin":10,"repsMax":12,"rir":1,"restSeconds":60}]'::jsonb, 'Nedelja je zatvorena. Ne zaboravi kardio ili sat hodanja.', 'public', 'asset:assets/trainers/kriss/trening-gornji-deo-b.jpg', 'Poslednji trening nedelje. Ramena i leđa, čisto i kontrolisano.'),
