  ('w_ab_glute_b', 'c_anja', 'Gluteus B', '[{"exerciseId":"ab_glute_bridge_kas","sets":3,"repsMin":8,"repsMax":10,"rir":1,"restSeconds":90},{"exerciseId":"ab_glute_legpress","sets":3,"repsMin":8,"repsMax":10,"rir":2,"restSeconds":120},{"exerciseId":"ab_step_up","sets":3,"repsMin":8,"repsMax":10,"rir":2,"restSeconds":75},{"exerciseId":"ab_abduction","sets":3,"repsMin":10,"repsMax":12,"rir":1,"restSeconds":60}]'::jsonb, 'Gluteus je gotov za ovu nedelju. Ponosna sam na tebe.', 'public', 'asset:assets/trainers/anja/trening-gluteus-b.jpg', 'Drugi gluteus dan. Step up polako, guraj kroz petu.'),
  ('w_ab_abs', 'c_anja', 'Trbuh', '[{"exerciseId":"ab_cable_crunch","sets":3,"repsMin":20,"repsMax":20,"rir":null,"restSeconds":45},{"exerciseId":"ab_lying_leg_raise","sets":3,"repsMin":20,"repsMax":20,"rir":null,"restSeconds":45},{"exerciseId":"ab_deadbug","sets":3,"repsMin":20,"repsMax":20,"rir":null,"restSeconds":45},{"exerciseId":"ab_side_plank_reach","sets":3,"repsMin":20,"repsMax":20,"rir":null,"restSeconds":45}]'::jsonb, 'Trbuh je odrađen. Vidimo se na sledećem treningu.', 'public', 'asset:assets/trainers/anja/trening-trbuh.jpg', 'Kratko i jako. Dvadeset ponavljanja, donja leđa na podu.')
