  ('p_mv_glutelab', 'c_minja', 'Glutelab', 'Četiri treninga nedeljno u teretani, sa fokusom na gluteus i noge. Dva dana nogu, dan za leđa i dan za gornji deo.', '{"w_mv_quad","w_mv_back","w_mv_hams","w_mv_upper"}', 8, 4, 'intermediate', 'muscle', 'gym', 'public', 'asset:assets/trainers/minja/program-glutelab.jpg'),
